-- RPC adapters for tests/isolation. Load AFTER fixtures.sql and rpc-fixtures.sql. Source: source1446 + tranche3.
-- Placeholder extensions used here (need resolver support): {v:tbl:kind} also for reservations(status)/staff_profiles(role)/cash_accounts(kind); {v:tbl.col} = column value of the victim row (registration_sessions.token, guest_phone_sessions.token, reservations.cversion = version of the confirmed priced victim).
-- Extension used by some call_sql: {v:cash_accounts:bank_account} and {v:staff_profiles:manager} = victim row of that table whose kind/role matches (needs resolver support).
create schema if not exists iso;
create table if not exists iso.rpc_adapter(signature text primary key, family text not null, mutates boolean not null, op text not null default 'read' check (op in ('read','create','update','delete')), call_sql text not null, control_sql text, reads_target boolean not null default false, caller_scoped boolean not null default false, note text);
create table if not exists iso.rpc_adapter_skip(signature text primary key, reason text not null);


