insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_expense_create(p jsonb)#nogl$s$,'financial',true,'create',$q$select fn_expense_create(jsonb_build_object('branch_id','{branch}','account_id','{v:cash_accounts:cash_box}','amount_halalas',100,'category_id','{v:expense_categories@nogl}','attachments',jsonb_build_array(jsonb_build_object('file_name','iso.png','data_base64','iVBORw0KGgo=')),'description','iso-{salt}','idempotency_key','exp-{salt}'))$q$,false,false,$q$select exists (select 1 from expense_vouchers where branch_id='{branch}'::uuid and description='iso-{salt}') and exists (select 1 from gl_accounts where expense_category_id='{v:expense_categories@nogl}'::uuid)$q$,$q$select not exists (select 1 from expense_vouchers where description='iso-{salt}' and branch_id<>'{branch}'::uuid)$q$,$q$select 'expense_vouchers'::text, e.id::text from (select e.id from expense_vouchers e where e.branch_id='{branch}'::uuid and e.idempotency_key='exp-{salt}') e union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='expense.created' and a.entity_type='expense_voucher' and a.entity_id in (select e.id from expense_vouchers e where e.branch_id='{branch}'::uuid and e.idempotency_key='exp-{salt}') union all select 'expense_attachments'::text, x.id::text from expense_attachments x where x.expense_id in (select e.id from expense_vouchers e where e.branch_id='{branch}'::uuid and e.idempotency_key='exp-{salt}') union all select 'journal_entries'::text, j.id::text from journal_entries j where j.organization_id='{org}'::uuid and j.source_type='expense' and j.source_id in (select e.id from expense_vouchers e where e.branch_id='{branch}'::uuid and e.idempotency_key='exp-{salt}') union all select 'journal_lines'::text, l.id::text from journal_lines l join journal_entries j on j.id=l.entry_id where j.organization_id='{org}'::uuid and j.source_type='expense' and j.source_id in (select e.id from expense_vouchers e where e.branch_id='{branch}'::uuid and e.idempotency_key='exp-{salt}') union all select 'document_sequences'::text, d.organization_id::text||'|'||d.kind||'|'||d.year::text from document_sequences d where d.organization_id='{org}'::uuid and d.kind in ('journal','expense') and d.year=extract(year from now())::int union all select 'gl_accounts'::text, g.id::text from gl_accounts g where g.expense_category_id='{v:expense_categories@nogl}'::uuid$q$,$n$VARIANT #nogl: lazy GL first use (fn_gl_for_category->fn_gl_child inserts one gl_accounts row). NOT executed in my PGlite (no nogl category there); expect_tables left null; fn_gl_system parent creation not covered.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_issue_credit_note(p_invoice uuid, p_reason text)#einv$s$,'financial',true,'create',$q$select fn_issue_credit_note('{v:invoices@einv}'::uuid,'iso-{salt}')$q$,false,false,$q$select exists (select 1 from invoices c where c.credit_note_of='{v:invoices@einv}'::uuid and c.doc_kind='credit_note')$q$,null,$q$select 'invoices'::text, c.id::text from invoices c where c.organization_id='{org}'::uuid and c.credit_note_of='{v:invoices@einv}'::uuid union all select 'document_sequences'::text, d.organization_id::text||'|'||d.kind||'|'||d.year::text from document_sequences d where d.organization_id='{org}'::uuid and d.kind='invoice' and d.year=extract(year from now())::int union all select 'review_items'::text, r.id::text from review_items r where r.organization_id='{org}'::uuid and r.kind='invoice_credit_note' and r.entity_id in (select c.id from invoices c where c.credit_note_of='{v:invoices@einv}'::uuid) union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='invoice.credit_note' and a.entity_id in (select c.id from invoices c where c.credit_note_of='{v:invoices@einv}'::uuid)$q$,$n$Needs isolation purpose einv invoice (real fn_staff_issue_invoice, then test-server-only e_invoice_ref=SYNTHETIC-LOCAL-NOT-REPORTED, per the seam doc). Touch contract (credit-note invoice row, invoice document_sequences row, review_item, audit) was EXACT on all 4 targets in my PGlite with the same marker set on my fixture invoice and decoy audit rows; not run in PG16 by me. Base fn_issue_credit_note stays unreported/refused path.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_staff_cancel_product_order(p_order uuid, p_reason text)#paidorder$s$,'reservation',true,'update',$q$select fn_staff_cancel_product_order('{v:product_orders@paidorder}'::uuid,'iso-{salt}')$q$,false,false,$q$select exists (select 1 from product_orders o where o.id='{v:product_orders@paidorder}'::uuid and o.status='cancelled' and o.cancel_reason='iso-{salt}') and exists (select 1 from product_orders o join financial_vouchers v on v.id=o.voucher_id where o.id='{v:product_orders@paidorder}'::uuid and v.status='cancelled') and exists (select 1 from product_orders o join housekeeping_tasks h on h.id=o.task_id where o.id='{v:product_orders@paidorder}'::uuid and h.status='cancelled')$q$,null,$q$select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='voucher.cancelled' and a.entity_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidorder}'::uuid) and a.details->>'reason' like '%: iso-{salt}' union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='product_order.cancelled' and a.entity_id='{v:product_orders@paidorder}'::uuid and a.details->>'reason'='iso-{salt}' union all select 'reservation_charges'::text, c.id::text from reservation_charges c where c.product_order_id='{v:product_orders@paidorder}'::uuid and c.total_halalas<0 union all select 'financial_vouchers'::text, (select o.voucher_id from product_orders o where o.id='{v:product_orders@paidorder}'::uuid)::text union all select 'document_sequences'::text, d.organization_id::text||'|'||d.kind||'|'||d.year::text from document_sequences d where d.organization_id='{org}'::uuid and d.kind='journal' and d.year=extract(year from now())::int union all select 'journal_entries'::text, j.id::text from journal_entries j where j.organization_id='{org}'::uuid and j.source_type='voucher' and j.source_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidorder}'::uuid) and j.reversal_of is not null union all select 'journal_lines'::text, l.id::text from journal_lines l join journal_entries j on j.id=l.entry_id where j.organization_id='{org}'::uuid and j.source_type='voucher' and j.source_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidorder}'::uuid) and j.reversal_of is not null union all select 'product_orders'::text, '{v:product_orders@paidorder}'::uuid::text union all select 'housekeeping_tasks'::text, o.task_id::text from product_orders o where o.id='{v:product_orders@paidorder}'::uuid union all select 'reservations'::text, o.reservation_id::text from product_orders o where o.id='{v:product_orders@paidorder}'::uuid union all select 'review_items'::text, r.id::text from review_items r where r.organization_id='{org}'::uuid and r.kind='voucher_cancelled' and r.entity_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidorder}'::uuid) and r.reason like '%: iso-{salt}'$q$,$n$Paid-order cancel branch (0068). Touch contract derived from a PGlite run diff on the isolation paidorder fixture (b4b0140f ported by me): 11 changed row groups incl. voucher reversal journal, negative charge(s), HK task cancel, reservation finance recompute. Charge rows are selected by product_order_id and total<0, so tax-line negatives (when tax is on for the target) are included but untested here (tax charge count was 1 in my run). PG16/executor proof is the isolation worker's.$n$) on conflict (signature) do nothing;
