insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_hk_start_task(p_task uuid)#roomcleaning$s$,'housekeeping',true,'update',$q$select fn_hk_start_task('{v:housekeeping_tasks@hkclean}'::uuid)$q$,false,false,$q$select exists (select 1 from housekeeping_tasks t join rooms r on r.id='{v:rooms@hkclean}'::uuid where t.id='{v:housekeeping_tasks@hkclean}'::uuid and t.status='in_progress' and r.cleanliness='in_progress')$q$,null,$q$select 'housekeeping_tasks'::text, '{v:housekeeping_tasks@hkclean}' union all select 'rooms'::text, '{v:rooms@hkclean}' union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='task.started' and a.entity_id='{v:housekeeping_tasks@hkclean}'::uuid$q$,$n$Call/effect/touch taken from isolation tranche15 tested-variant-calls (PG16, 4 targets exact); NOT executed in my PGlite (no hkclean fixture). Source 0007b fn_hk_start_task: room_cleaning task sets rooms.cleanliness in_progress.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_hk_cancel_task(p_task uuid, p_reason text)#inprogress$s$,'housekeeping',true,'update',$q$select fn_hk_cancel_task('{v:housekeeping_tasks@hkcancel}'::uuid,'iso-{salt}')$q$,false,false,$q$select exists (select 1 from housekeeping_tasks t where t.id='{v:housekeeping_tasks@hkcancel}'::uuid and t.status='cancelled') and exists (select 1 from housekeeping_tasks t join rooms r on r.id=t.room_id where t.id='{v:housekeeping_tasks@hkcancel}'::uuid and r.cleanliness='dirty')$q$,null,$q$select 'housekeeping_tasks'::text, '{v:housekeeping_tasks@hkcancel}' union all select 'rooms'::text, t.room_id::text from housekeeping_tasks t where t.id='{v:housekeeping_tasks@hkcancel}'::uuid union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='task.cancelled' and a.entity_id='{v:housekeeping_tasks@hkcancel}'::uuid and a.details->>'reason'='iso-{salt}'$q$,$n$From isolation tranche15 tested-variant-calls (PG16 exact); NOT executed in my PGlite. Source 0007b fn_hk_cancel_task: rooms.cleanliness in_progress -> dirty only.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_staff_add_service(p_reservation uuid, p_service uuid, p_quantity numeric, p_note text)#latecheckout$s$,'reservation',true,'create',$q$select fn_staff_add_service('{v:reservations@latecheckout}'::uuid,'{v:service_definitions@latecheckout}'::uuid,1,'iso')$q$,false,false,$q$select exists (select 1 from reservation_charges c where c.reservation_id='{v:reservations@latecheckout}'::uuid and c.service_definition_id='{v:service_definitions@latecheckout}'::uuid) and exists (select 1 from reservations r where r.id='{v:reservations@latecheckout}'::uuid and r.late_checkout_until is not null)$q$,null,$q$select 'reservation_charges'::text, c.id::text from reservation_charges c where c.reservation_id='{v:reservations@latecheckout}'::uuid and c.service_definition_id='{v:service_definitions@latecheckout}'::uuid union all select 'reservations'::text, '{v:reservations@latecheckout}' union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='reservation.service_added' and a.entity_id='{v:reservations@latecheckout}'::uuid$q$,$n$From isolation tranche15 (PG16 exact; the service_definition_id filter is required, else listed_unchanged); NOT executed in my PGlite. Source 0053/0033 fn_staff_add_service: late_checkout service also sets charge purpose and reservations.late_checkout_until.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_staff_cancel_product_order(p_order uuid, p_reason text)#paidordertax$s$,'reservation',true,'update',$q$select fn_staff_cancel_product_order('{v:product_orders@paidordertax}'::uuid,'iso-{salt}')$q$,false,false,$q$select exists (select 1 from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid and o.status='cancelled' and o.cancel_reason='iso-{salt}') and exists (select 1 from product_orders o join financial_vouchers v on v.id=o.voucher_id where o.id='{v:product_orders@paidordertax}'::uuid and v.status='cancelled') and exists (select 1 from product_orders o join housekeeping_tasks h on h.id=o.task_id where o.id='{v:product_orders@paidordertax}'::uuid and h.status='cancelled') and exists (select 1 from reservation_charges c where c.product_order_id='{v:product_orders@paidordertax}'::uuid and c.kind='tax' and c.total_halalas<0) and exists (select 1 from reservation_charges c where c.product_order_id='{v:product_orders@paidordertax}'::uuid and c.kind='addon' and c.total_halalas<0)$q$,null,$q$select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='voucher.cancelled' and a.entity_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid) and a.details->>'reason' like '%: iso-{salt}' union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='product_order.cancelled' and a.entity_id='{v:product_orders@paidordertax}'::uuid and a.details->>'reason'='iso-{salt}' union all select 'reservation_charges'::text, c.id::text from reservation_charges c where c.product_order_id='{v:product_orders@paidordertax}'::uuid and c.total_halalas<0 union all select 'financial_vouchers'::text, (select o.voucher_id from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid)::text union all select 'document_sequences'::text, d.organization_id::text||'|'||d.kind||'|'||d.year::text from document_sequences d where d.organization_id='{org}'::uuid and d.kind='journal' and d.year=extract(year from now())::int union all select 'journal_entries'::text, j.id::text from journal_entries j where j.organization_id='{org}'::uuid and j.source_type='voucher' and j.source_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid) and j.reversal_of is not null union all select 'journal_lines'::text, l.id::text from journal_lines l join journal_entries j on j.id=l.entry_id where j.organization_id='{org}'::uuid and j.source_type='voucher' and j.source_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid) and j.reversal_of is not null union all select 'product_orders'::text, '{v:product_orders@paidordertax}'::uuid::text union all select 'housekeeping_tasks'::text, o.task_id::text from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid union all select 'reservations'::text, o.reservation_id::text from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid union all select 'review_items'::text, r.id::text from review_items r where r.organization_id='{org}'::uuid and r.kind='voucher_cancelled' and r.entity_id=(select o.voucher_id from product_orders o where o.id='{v:product_orders@paidordertax}'::uuid) and r.reason like '%: iso-{salt}'$q$,$n$Paid-order cancel branch (0068) on a tax-ON stay (isolation paidordertax fixture 1806: 15% products tax snapshot, tax-exclusive, one addon + one positive tax charge). Touch contract derived from a PGlite run diff on my port of that fixture block: 13 rows = the 12 of #paidorder plus the negative tax reservation_charges row (charges selected by product_order_id and total<0). Effect asserts negative addon AND negative tax charge exist. Pay-setup notification is not in the cancel diff, so it is not in touch. PG16/executor proof is the isolation worker's.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,expect_tables,touch_sql,note) values ($s$fn_admin_set_product_branch(p_product uuid, p_branch uuid, p_available boolean)$s$,'admin',true,'update',$q$select fn_admin_set_product_branch('{v:products}'::uuid,'{branch}'::uuid,true)$q$,false,false,$q$select exists (select 1 from product_branches where product_id='{v:products}'::uuid and branch_id='{branch}'::uuid and available and organization_id='{org}'::uuid)$q$,array['audit_events','product_branches'],$q$select 'product_branches'::text, '{v:products}'||'|'||'{branch}' union all select 'audit_events'::text,a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.entity_id='{v:products}'::uuid and a.entity_type='product' and a.action='product.availability_changed' and a.details->'before'->>'available'='false' and a.details->'after'->>'available'='true' and a.details->'after'->>'branch'=(select name_ar from branches where id='{branch}'::uuid)$q$,$n$Trigger-enabled source0068upsert. Canonical proof supplies absent/false slot explicitly and unrelated audit decoys. Not a replacement for generic table CRUD role-operation coverage.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_guest_departure(p_token text, p_via text)#departure$s$,'guest-capability',true,'update',$q$select fn_guest_departure('{v:registration_sessions.token@departure}','page') from (select fn_guest_departure_instructions('{v:registration_sessions.token@departure}') x offset 0) i$q$,false,false,$q$select exists (select 1 from reservations r where r.id='{v:reservations@departure}'::uuid and r.organization_id='{org}'::uuid and r.guest_departed_at is not null and r.guest_departed_via='page' and r.departure_instructions_at is not null) and exists (select 1 from alert_events e where e.branch_id='{branch}'::uuid and e.event='guest_departed' and e.ref_key='departed:'||'{v:reservations@departure}')$q$,null,$q$select 'reservations'::text, '{v:reservations@departure}' union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='journey.guest_departed' and a.entity_type='reservation' and a.entity_id='{v:reservations@departure}'::uuid and a.details->'after'->>'via'='page' union all select 'alert_events'::text, e.id::text from alert_events e where e.branch_id='{branch}'::uuid and e.event='guest_departed' and e.ref_key='departed:'||'{v:reservations@departure}'$q$,$n$ACTOR=anon guest (x-hotel-slug of the target hotel), credential = the departure stay's own registration token (fixture purpose departure, rpc-fixtures-departure.sql). The call first runs fn_guest_departure_instructions on the same token inside one statement (source 0070: fn_departure_confirm raises instructions_first otherwise; this is what the guest page does). PGlite diff on 4 targets (claims cleared, anon): reservations (guest_departed_at/via, departure_instructions_at), audit journey.guest_departed (after.via=page), alert_events guest_departed ref_key departed:<reservation>. Free-checkout hour held to 23:59 by the fixture, so the late-hours charge branch is NOT covered; already-departed and not-departure-day branches not covered.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_guest_departure_instructions(p_token text)#departure$s$,'guest-capability',true,'update',$q$select fn_guest_departure_instructions('{v:registration_sessions.token@departure}')$q$,false,false,$q$select exists (select 1 from reservations r where r.id='{v:reservations@departure}'::uuid and r.organization_id='{org}'::uuid and r.departure_instructions_at is not null and r.guest_departed_at is null)$q$,null,$q$select 'reservations'::text, '{v:reservations@departure}'$q$,$n$ACTOR=anon guest (x-hotel-slug of the target hotel), credential = the departure stay's own registration token (fixture purpose departure, rpc-fixtures-departure.sql). Source 0070 fn_departure_instructions: sets reservations.departure_instructions_at once (status checked_in, room set, check_out <= branch today, not departed). PGlite diff on 4 targets: exactly that 1 reservation row. Already-set / not-in-stay branches not covered.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_refund(p jsonb)#othermethod$s$,'financial',true,'update',$q$select fn_refund(jsonb_build_object('kind','refund','reservation_id','{v:reservations@refundother}','amount_halalas',1,'method','ota_deferred','method_reason','iso-{salt}','reason','iso-{salt}','idempotency_key','rfo-{salt}'))$q$,false,false,$q$select exists (select 1 from financial_vouchers v where v.reservation_id='{v:reservations@refundother}'::uuid and v.kind='refund' and v.method='ota_deferred' and v.idempotency_key='rfo-{salt}' and v.account_id is null) and exists (select 1 from review_items r where r.organization_id='{org}'::uuid and r.kind='refund_other_method' and r.entity_id in (select v.id from financial_vouchers v where v.reservation_id='{v:reservations@refundother}'::uuid and v.idempotency_key='rfo-{salt}'))$q$,null,$q$select 'financial_vouchers'::text, v.id::text from (select v.id from financial_vouchers v where v.reservation_id='{v:reservations@refundother}'::uuid and v.idempotency_key='rfo-{salt}') v union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='voucher.refund_created' and a.entity_type='voucher' and a.entity_id in (select v.id from financial_vouchers v where v.reservation_id='{v:reservations@refundother}'::uuid and v.idempotency_key='rfo-{salt}') union all select 'journal_entries'::text, j.id::text from journal_entries j where j.organization_id='{org}'::uuid and j.source_type='voucher' and j.source_id in (select v.id from financial_vouchers v where v.reservation_id='{v:reservations@refundother}'::uuid and v.idempotency_key='rfo-{salt}') union all select 'journal_lines'::text, l.id::text from journal_lines l join journal_entries j on j.id=l.entry_id where j.organization_id='{org}'::uuid and j.source_type='voucher' and j.source_id in (select v.id from financial_vouchers v where v.reservation_id='{v:reservations@refundother}'::uuid and v.idempotency_key='rfo-{salt}') union all select 'document_sequences'::text, d.organization_id::text||'|'||d.kind||'|'||d.year::text from document_sequences d where d.organization_id='{org}'::uuid and d.kind in ('journal','voucher') and d.year=extract(year from now())::int union all select 'reservations'::text, '{v:reservations@refundother}' union all select 'review_items'::text, r.id::text from review_items r where r.organization_id='{org}'::uuid and r.kind='refund_other_method' and r.entity_id in (select v.id from financial_vouchers v where v.reservation_id='{v:reservations@refundother}'::uuid and v.idempotency_key='rfo-{salt}')$q$,$n$Warm source-linked GL branch, dedicated refundother reservation. Cold first-use GL creation is separately qualified by source_id, not assumed account code, not part of this touch. Refund by a method other than the stay's receipts (0054 fn_refund): method ota_deferred (active, no account/reference needed) with method_reason, on the checked_in stay paid in cash. Creates the refund voucher + audit voucher.refund_created + journal entry/lines + voucher/journal sequences + reservation totals + review_item refund_other_method (details paid_methods/method). The ota_deferred receivable GL account (code 12102) is created lazily on first use, so it appears in the touch only while the org has none yet (PGlite diff showed it created on all 4 targets from the standard fixtures). Bank-account methods (pos/bank_transfer) need a default bank cash_account and are NOT covered. No notifications observed. Owner actor with voucher.refund.$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_staff_check_out(p jsonb)#checkout$s$,'reservation',true,'update',$q$select fn_staff_check_out(jsonb_build_object('reservation_id','{v:reservations@checkout}'))$q$,false,false,$q$select exists (select 1 from reservations r where r.id='{v:reservations@checkout}'::uuid and r.status in ('checked_out','closed') and r.actual_check_out is not null) and exists (select 1 from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.status='issued') and exists (select 1 from housekeeping_tasks h where h.reservation_id='{v:reservations@checkout}'::uuid and h.status='pending')$q$,null,$q$select 'reservations'::text, '{v:reservations@checkout}' union all select 'rooms'::text, r.room_id::text from reservations r where r.id='{v:reservations@checkout}'::uuid union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='reservation.checked_out' and a.details->'before'->>'status'='checked_in' and a.details->'after'->>'status'='checked_out' and a.entity_type='reservation' and a.entity_id in (select '{v:reservations@checkout}'::uuid) union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='reservation.closed' and a.entity_type='reservation' and a.entity_id in (select '{v:reservations@checkout}'::uuid) union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='invoice.issued' and a.entity_type='invoice' and a.entity_id in (select i.id from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.organization_id='{org}'::uuid) union all select 'invoices'::text, i.id::text from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.organization_id='{org}'::uuid union all select 'reservation_charges'::text, c.id::text from reservation_charges c where c.reservation_id='{v:reservations@checkout}'::uuid and c.invoice_id in (select i.id from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.organization_id='{org}'::uuid) union all select 'reservation_allocations'::text, a.id::text from reservation_allocations a where a.reservation_id='{v:reservations@checkout}'::uuid and a.status='closed' union all select 'document_sequences'::text, d.organization_id::text||'|'||d.kind||'|'||d.year::text from document_sequences d where d.organization_id='{org}'::uuid and d.kind='invoice' and d.year=extract(year from now())::int union all select 'housekeeping_tasks'::text, h.id::text from housekeeping_tasks h where h.reservation_id='{v:reservations@checkout}'::uuid and h.description='تنظيف بعد المغادرة' union all select 'journey_messages'::text, j.id::text from journey_messages j where j.reservation_id='{v:reservations@checkout}'::uuid and j.kind='checkout_confirmed' union all select 'alert_events'::text, e.id::text from alert_events e where e.branch_id='{branch}'::uuid and e.event='message_failed' and e.ref_key='channel:'||'{branch}'||':'||fn_branch_today('{branch}'::uuid)::text union all select 'notifications'::text, n.id::text from notifications n where n.branch_id='{branch}'::uuid and n.audience='supervisor' and n.link='/staff/housekeeping' and n.body='غرفة '||(select ro.room_number from reservations r join rooms ro on ro.id=r.room_id where r.id='{v:reservations@checkout}'::uuid) union all select 'task_types'::text, t.id::text from task_types t where t.organization_id='{org}'::uuid and t.branch_id='{branch}'::uuid and t.code='room_cleaning'$q$,$n$Dedicated synthetic stay (purpose checkout, rpc-fixtures-checkout.sql): checked in through the production RPCs, own room without keybox, check_out = today (test-only seed UPDATE), balance paid in full. fn_staff_check_out (0053): reservation checked_out then closed by fn_sync_closed, room cleaning/dirty, allocations closed, housekeeping cleaning task, supervisor notification (title by room, no keybox), invoice + charge link + invoice sequence, audits reservation.checked_out/reservation.closed/invoice.issued, journey_messages checkout_confirmed (status skipped, reason channel_unavailable: no WhatsApp channel in fixtures, nothing is sent) and alert_events message_failed. task_types room_cleaning is created lazily on first use in the branch (cold-state row). Early-departure, balance-due, duplicate (already checked out), keybox and connected-channel branches NOT covered. Owner actor. COLD-ONLY adapter requires absent room_cleaning type and branchday channel alert; standalone proof subtracts precisely preexisting lazy/dedup rows for its separate warm run, this adapter does not. Lazy/dedup state: task_types room_cleaning and the branch-day channel alert (ref_key channel:<branch>:<today>) are created only on the first check-out in a cold branch; a warm branch would show them missing (warm state NOT tested).$n$) on conflict (signature) do nothing;
insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,guard_sql,touch_sql,note) values ($s$fn_staff_checkout(p_reservation uuid, p_override_reason text)#checkout$s$,'reservation',true,'update',$q$select fn_staff_checkout('{v:reservations@checkout}'::uuid,null)$q$,false,false,$q$select exists (select 1 from reservations r where r.id='{v:reservations@checkout}'::uuid and r.status in ('checked_out','closed') and r.actual_check_out is not null) and exists (select 1 from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.status='issued') and exists (select 1 from housekeeping_tasks h where h.reservation_id='{v:reservations@checkout}'::uuid and h.status='pending')$q$,null,$q$select 'reservations'::text, '{v:reservations@checkout}' union all select 'rooms'::text, r.room_id::text from reservations r where r.id='{v:reservations@checkout}'::uuid union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='reservation.checked_out' and a.details->'before'->>'status'='checked_in' and a.details->'after'->>'status'='checked_out' and a.entity_type='reservation' and a.entity_id in (select '{v:reservations@checkout}'::uuid) union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='reservation.closed' and a.entity_type='reservation' and a.entity_id in (select '{v:reservations@checkout}'::uuid) union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='invoice.issued' and a.entity_type='invoice' and a.entity_id in (select i.id from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.organization_id='{org}'::uuid) union all select 'invoices'::text, i.id::text from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.organization_id='{org}'::uuid union all select 'reservation_charges'::text, c.id::text from reservation_charges c where c.reservation_id='{v:reservations@checkout}'::uuid and c.invoice_id in (select i.id from invoices i where i.reservation_id='{v:reservations@checkout}'::uuid and i.organization_id='{org}'::uuid) union all select 'reservation_allocations'::text, a.id::text from reservation_allocations a where a.reservation_id='{v:reservations@checkout}'::uuid and a.status='closed' union all select 'document_sequences'::text, d.organization_id::text||'|'||d.kind||'|'||d.year::text from document_sequences d where d.organization_id='{org}'::uuid and d.kind='invoice' and d.year=extract(year from now())::int union all select 'housekeeping_tasks'::text, h.id::text from housekeeping_tasks h where h.reservation_id='{v:reservations@checkout}'::uuid and h.description='تنظيف بعد المغادرة' union all select 'journey_messages'::text, j.id::text from journey_messages j where j.reservation_id='{v:reservations@checkout}'::uuid and j.kind='checkout_confirmed' union all select 'alert_events'::text, e.id::text from alert_events e where e.branch_id='{branch}'::uuid and e.event='message_failed' and e.ref_key='channel:'||'{branch}'||':'||fn_branch_today('{branch}'::uuid)::text union all select 'notifications'::text, n.id::text from notifications n where n.branch_id='{branch}'::uuid and n.audience='supervisor' and n.link='/staff/housekeeping' and n.body='غرفة '||(select ro.room_number from reservations r join rooms ro on ro.id=r.room_id where r.id='{v:reservations@checkout}'::uuid) union all select 'task_types'::text, t.id::text from task_types t where t.organization_id='{org}'::uuid and t.branch_id='{branch}'::uuid and t.code='room_cleaning'$q$,$n$Thin wrapper over fn_staff_check_out (0053) with no override reason, so the same contract as fn_staff_check_out#checkout (identical PGlite touch/effect). Dedicated synthetic stay (purpose checkout, rpc-fixtures-checkout.sql): checked in through the production RPCs, own room without keybox, check_out = today (test-only seed UPDATE), balance paid in full. fn_staff_check_out (0053): reservation checked_out then closed by fn_sync_closed, room cleaning/dirty, allocations closed, housekeeping cleaning task, supervisor notification (title by room, no keybox), invoice + charge link + invoice sequence, audits reservation.checked_out/reservation.closed/invoice.issued, journey_messages checkout_confirmed (status skipped, reason channel_unavailable: no WhatsApp channel in fixtures, nothing is sent) and alert_events message_failed. task_types room_cleaning is created lazily on first use in the branch (cold-state row). Early-departure, balance-due, duplicate (already checked out), keybox and connected-channel branches NOT covered. Owner actor. COLD-ONLY adapter requires absent room_cleaning type and branchday channel alert; standalone proof subtracts precisely preexisting lazy/dedup rows for its separate warm run, this adapter does not. Lazy/dedup state: task_types room_cleaning and the branch-day channel alert (ref_key channel:<branch>:<today>) are created only on the first check-out in a cold branch; a warm branch would show them missing (warm state NOT tested).$n$) on conflict (signature) do nothing;
