insert into iso.rpc_adapter(signature,family,mutates,op,call_sql,reads_target,caller_scoped,effect_sql,expect_tables,touch_sql,note) values ($s$fn_admin_whatsapp_security(p_branch uuid, p jsonb)$s$,'admin',true,'update',$q$select fn_admin_whatsapp_security('{branch}'::uuid, jsonb_build_object('alert_new_contacts_per_hour',17))$q$,false,false,$q$select exists (select 1 from branch_whatsapp_channels x where x.branch_id='{branch}'::uuid and x.organization_id='{org}'::uuid and x.alert_new_contacts_per_hour=17) and not exists (select 1 from branch_whatsapp_channels w where w.organization_id='{org}'::uuid and (w.bridge_key_hash is not null)) and exists (select 1 from audit_events a where a.organization_id='{org}'::uuid and a.action='whatsapp_channel_updated' and a.entity_type='branch' and a.entity_id in ('{branch}'::uuid))$q$,array['audit_events','branch_whatsapp_channels'],$q$select 'branch_whatsapp_channels'::text,'{branch}' union all select 'audit_events'::text, a.id::text from audit_events a where a.organization_id='{org}'::uuid and a.action='whatsapp_channel_updated' and a.entity_type='branch' and a.entity_id in ('{branch}'::uuid)$q$,$n$PGlite owner control on 4 targets: effect false->true, touch/changed rows exact (ck9). Foreign-hotel owner denied, no row change. Single non-secret field only (alert_new_contacts_per_hour / human_pause_minutes); no token, secret, bridge key, mode or phone sent; effect also asserts no keyed bridge channel exists in the org; whatsapp_outbox/journey tables unchanged (exact changed-row set). Base fixture already holds whatsapp_outbox rows, so the check is unchanged-not-zero; update-existing, validation and duplicate branches not covered.$n$) on conflict (signature) do nothing;
